const input = $input.first().json;

const nombre = input['Nombre completo'] || '';
const email = input['Email'] || '';
const telefono = input['Teléfono'] || '';
const empresa = input['Empresa'] || '';
const mensaje = input['¿En qué podemos ayudarte?'] || '';

const texto = mensaje.toLowerCase();

function includesAny(text, list) {
  return list.some((k) => text.includes(k));
}

const kwQueja = ['queja', 'reclamo', 'reclamacion', 'reclamación', 'insatisfech', 'mal servicio', 'decepcionad', 'molest'];
const kwSoporte = ['problema', 'error', 'no funciona', 'falla', 'fallo', 'soporte', 'incidencia', 'ayuda con'];
const kwPresupuesto = ['presupuesto', 'cotizacion', 'cotización', 'precio', 'coste', 'costo', 'tarifa', 'plan'];
const kwUrgente = ['urgente', 'inmediato', 'lo antes posible', 'hoy mismo', 'cuanto antes'];

let categoria = 'Información general';
let prioridad = 'Baja';

if (includesAny(texto, kwQueja)) {
  categoria = 'Reclamación';
  prioridad = 'Alta';
} else if (includesAny(texto, kwSoporte)) {
  categoria = 'Soporte técnico';
  prioridad = includesAny(texto, kwUrgente) ? 'Alta' : 'Media';
} else if (includesAny(texto, kwPresupuesto)) {
  categoria = 'Presupuesto / Cotización';
  prioridad = 'Media';
}

if (includesAny(texto, kwUrgente) && prioridad !== 'Alta') {
  prioridad = 'Alta';
}

const plantillas = {
  'Presupuesto / Cotización': {
    asunto: `${nombre}, aquí tienes la información sobre tu presupuesto`,
    cuerpo: `Hola ${nombre},\n\nGracias por contactarnos y por el interés en nuestros servicios${empresa ? ' para ' + empresa : ''}.\n\nHemos recibido tu solicitud de presupuesto y nuestro equipo comercial ya la está revisando. Te enviaremos una propuesta personalizada en menos de 24-48 horas laborables.\n\nSi mientras tanto quieres añadir algún detalle a tu solicitud, simplemente responde a este correo.\n\nUn saludo,\nEl equipo`,
  },
  'Soporte técnico': {
    asunto: `${nombre}, hemos recibido tu incidencia`,
    cuerpo: `Hola ${nombre},\n\nGracias por avisarnos. Hemos registrado tu incidencia y nuestro equipo técnico ya está trabajando en ella.\n\nNos pondremos en contacto contigo lo antes posible${telefono ? ' al número ' + telefono : ''} para resolverlo.\n\nUn saludo,\nEl equipo`,
  },
  'Reclamación': {
    asunto: `${nombre}, lamentamos los inconvenientes`,
    cuerpo: `Hola ${nombre},\n\nSentimos mucho la experiencia que nos cuentas. Tu mensaje ha sido trasladado a un responsable, que se pondrá en contacto contigo en las próximas horas para resolverlo.\n\nGracias por tu paciencia y por darnos la oportunidad de solucionarlo.\n\nUn saludo,\nEl equipo`,
  },
  'Información general': {
    asunto: `${nombre}, gracias por contactarnos`,
    cuerpo: `Hola ${nombre},\n\nGracias por escribirnos. Hemos recibido tu mensaje y te responderemos personalmente en breve con la información que necesitas.\n\nUn saludo,\nEl equipo`,
  },
};

const plantilla = plantillas[categoria];

return [
  {
    json: {
      nombre,
      email,
      telefono,
      empresa,
      mensaje,
      categoria,
      prioridad,
      fecha: new Date().toISOString(),
      emailAsunto: plantilla.asunto,
      emailCuerpo: plantilla.cuerpo,
    },
  },
];
